function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function db(){if(!openDB)openDB=new Promise((ok,no)=>{let r=indexedDB.open('frond-advisor',1);r.onupgradeneeded=()=>r.result.createObjectStore('studies');r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});return openDB}
async function getSaved(){try{let d=await db();return await new Promise((ok,no)=>{let t=d.transaction('studies').objectStore('studies').get('current');t.onsuccess=()=>ok(t.result);t.onerror=()=>no(t.error)})}catch{return JSON.parse(localStorage.getItem('frond-study-3')||'null')}}
