function cards(){const sel=project.active;$('#variantCount').textContent=project.variants.length;$('#variantGrid').innerHTML=project.variants.map(v=>'<button class="variant-card '+(sel===v.id?'active':'')+'" data-card="'+esc(v.id)+'" aria-pressed="'+(sel===v.id)+'"><div class="card-picture"><canvas aria-hidden="true"></canvas><span class="card-code">'+code(v)+'</span>'+(sel===v.id?'<span class="selected-mark">'+icon('check')+'</span>':'')+'</div><div class="card-body"><div><h3>'+esc(v.name)+'</h3></div><small><span class="card-type" style="background:'+systems[v.system].color+'"></span>'+esc(systems[v.system].family)+'</small></div></button>').join('');
 $$('.variant-card').forEach((el,i)=>{swatch(el.querySelector('canvas'),project.variants[i]);el.onclick=()=>{project.active=el.dataset.card;renderWorkspace();changed()}})}
