function headings(){$('#projectName').textContent=project.name;$('#projectKind').textContent=project.model?'IMPORTED PROJECT':'DEMO PROJECT';$('#projectMeta').innerHTML='<span>'+icon('map-pin')+esc(project.location||'Location unspecified')+'</span><i class="sep"></i><span>'+icon('building-2')+esc(project.use||'Building')+'</span><i class="sep"></i><span>'+esc(project.levels)+' storey'+(project.levels===1?'':'s')+'</span>';document.title=project.name+' · Frond'}
function slider(key,label,min,max,step,unit){let val=active()[key],pc=(val-min)/(max-min)*100;return '<div class="slider-row"><label class="slider-head" for="p-'+key+'">'+label+'<output class="num" id="out-'+key+'">'+fmt(val)+unit+'</output></label><input id="p-'+key+'" data-param="'+key+'" data-unit="'+unit+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+val+'" style="--pct:'+pc+'%"></div>'}
function formSelect(id,label,options,val){return '<label class="field">'+label+'<select id="'+id+'" class="std">'+selectOpts(options,val)+'</select></label>'}
