function refreshEdit(){inspector();cards();requestDraw(true);changed()}
function previewMotion(){
 cancelAnimationFrame(motionFrame);const variant=active(),start=performance.now(),orig=variant.angle||0;let prior=0;
 function step(now){if(tab!=='workspace'||active()!==variant||!['kinetic','bionic'].includes(variant.system))return;let t=(now-start)/2600;if(t>=1){requestDraw(true);return}if(now-prior>45){let angle=orig+(72-orig)*Math.sin(Math.PI*t)**2;scene=buildScene(project,{...variant,angle},viewOptions);requestDraw();prior=now}motionFrame=requestAnimationFrame(step)}motionFrame=requestAnimationFrame(step)
}
function sunLabel(){const s=sunVector(sunState.month,sunState.hour),alt=Math.asin(s[2])*180/Math.PI,az=(Math.atan2(s[0],s[1])*180/Math.PI+360)%360,h=Math.floor(sunState.hour),m=Math.round((sunState.hour-h)*60);
 $('#sunOut').textContent='21 '+MONTH_NAMES[sunState.month]+' · '+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+(alt>0?' · sun '+Math.round(alt)+'° up, '+Math.round(az)+'°':' · after sunset');$('#sunHour').value=sunState.hour;$('#sunMonth').value=sunState.month;$('#sunPlay').innerHTML=icon(sunState.play?'pause':'play');$('#sunPlay').setAttribute('aria-label',sunState.play?'Pause day':'Play day');$('#traffic').checked=viewOptions.traffic}
function sunPanel(){$('#sunMonth').innerHTML=MONTH_NAMES.map((n,i)=>'<option value="'+i+'">21 '+n+'</option>').join('');$('#sunMonth').onchange=e=>{sunState.month=Number(e.target.value);sunLabel();requestDraw()};$('#sunHour').oninput=e=>{sunState.hour=Number(e.target.value);sunLabel();requestDraw()};$('#sunPlay').onclick=()=>{sunState.play=!sunState.play;sunLabel()};$('#traffic').onchange=e=>{viewOptions.traffic=e.target.checked;requestDraw()};sunLabel()}
function animate(now){const dt=Math.min(.1,(now-lastTick)/1000);if(now-lastTick>33){lastTick=now;if(tab==='workspace'&&!document.hidden){if(sunState.play){sunState.hour+=dt*1.5;if(sunState.hour>20)sunState.hour=5;sunLabel()}if(sunState.play||(viewOptions.traffic&&!project.model&&tool!=='select'))requestDraw()}}requestAnimationFrame(animate)}
function toolbar(){$('#tools').innerHTML=[['orbit','Orbit model'],['hand','Pan model'],['mouse-pointer-2','Select elevation'],['|'],['minus','Zoom out'],['plus','Zoom in'],['scan','Fit model']].map(([id,name])=>id==='|'?'<i class="tool-sep"></i>':'<button title="'+name+'" aria-label="'+name+'" data-view-tool="'+id+'" class="'+(id===(tool==='select'?'mouse-pointer-2':tool)?'active':'')+'">'+icon(id)+'</button>').join('');
 $$('[data-view-tool]').forEach(n=>n.onclick=()=>{let t=n.dataset.viewTool;if(t==='minus'||t==='plus')camera.zoom=Math.max(.28,Math.min(4,camera.zoom*(t==='plus'?1.18:1/1.18)));else if(t==='scan'){camera=workCam();view='Axonometric';$('#cameraName').textContent=view}else{tool=t==='mouse-pointer-2'?'select':t;$('#viewHelp').textContent=tool==='orbit'?'Drag to orbit · Scroll to zoom':tool==='hand'?'Drag to pan · Scroll to zoom':'Click a façade to target its elevation';toolbar()}requestDraw()})}
function renderWorkspace(){cancelAnimationFrame(motionFrame);headings();inspector();cards();toolbar();$('#viewLabel').textContent=viewOptions.cut?'Section · Level '+viewOptions.cut:'Exterior view';requestDraw(true)}
function setTab(k){if(!['workspace','compare','results'].includes(k))k='workspace';tab=k;for(let sel of ['workspace','compare','results'])$('#'+sel).hidden=sel!==k;$$('[data-tab]').forEach(n=>{n.classList.toggle('active',n.dataset.tab===k);n.setAttribute('aria-current',n.dataset.tab===k?'page':'false')});if(k==='workspace')renderWorkspace();if(k==='compare')compare();if(k==='results')results();history.replaceState(null,'','#'+k)}
function modal(title,body,foot){let d=$('#dialog');if(d.open)d.close();d.setAttribute('aria-label',title);d.innerHTML='<div class="modal-head"><h2>'+title+'</h2><button aria-label="Close dialog" class="quiet-icon" data-close>'+icon('x')+'</button></div><div class="modal-body">'+body+'</div><div class="modal-foot">'+(foot||'')+'</div>';d.querySelectorAll('[data-close]').forEach(n=>n.onclick=()=>d.close());d.showModal();return d}
const cancel='<button class="button secondary" data-close>Cancel</button>';
function popAt(el,html){let p=$('#pop');p.innerHTML='<div class="popover">'+html+'</div>';let a=el.getBoundingClientRect(),s=p.firstChild;s.style.left=Math.max(8,Math.min(innerWidth-s.offsetWidth-8,a.right-s.offsetWidth))+'px';s.style.top=Math.min(innerHeight-s.offsetHeight-8,a.bottom+5)+'px';return s}
function menu(el,entries){let p=popAt(el,entries.map(([label,_,chosen])=>'<button class="'+(chosen?'chosen':'')+'">'+esc(label)+'</button>').join(''));[...p.querySelectorAll('button')].forEach((n,i)=>n.onclick=()=>{p.remove();entries[i][1]()})}
function projectForm(){let d=modal('Project details','<div class="fields"><label class="field">Project name<input id="pn" maxlength="70" value="'+esc(project.name)+'"></label><label class="field">Location<input id="pl" maxlength="70" value="'+esc(project.location)+'"></label><div class="fields two"><label class="field">Building use<input id="pu" maxlength="40" value="'+esc(project.use)+'"></label><label class="field">Cost currency<input id="pc" maxlength="8" value="'+esc(project.currency||'USD')+'"></label></div></div><p class="field-hint">Location and use describe the study. Weather and simulation inputs can be added in the analysis stage.</p>',cancel+'<button id="saveProject" class="button primary">Save details</button>');$('#saveProject').onclick=()=>{let n=$('#pn').value.trim();if(!n){$('#pn').focus();return}Object.assign(project,{name:n,location:$('#pl').value.trim(),use:$('#pu').value.trim(),currency:$('#pc').value.trim()||'USD'});d.close();headings();setTab(tab);changed()}}
function variantForm(duplicate=false){let prior=active(),baseSys=prior.system==='original'?'trellis':prior.system;let opt={...systems};delete opt.original;if(!prior.custom)delete opt.custom;let d=modal(duplicate?'Duplicate variant':'New design variant','<div class="fields"><label class="field">Variant name<input id="vn" maxlength="50" value="'+esc(duplicate?prior.name+' copy':'')+'" placeholder="e.g. West-facing terracotta fins"></label>'+formSelect('vs','Façade system',opt,baseSys)+formSelect('ve','Target elevation',dirNames,prior.elevation)+'<p class="field-hint">Each variant is compared with the original envelope on the same building.</p></div>',cancel+'<button class="button primary" id="vc">'+icon('plus')+'Create variant</button>');$('#vc').onclick=()=>{let sys=$('#vs').value,v={...structuredClone(prior),id:uid(),name:$('#vn').value.trim()||systems[sys].name,system:sys,elevation:$('#ve').value};project.variants.push(v);project.active=v.id;project.checked.push(v.id);d.close();setTab('workspace');changed();toast('Variant added')}}
function renameForm(){let v=active(),d=modal('Edit variant','<label class="field">Variant name<input id="vn" value="'+esc(v.name)+'" maxlength="50"></label>', '<button class="button danger" id="deleteV">Delete variant</button>'+cancel+'<button class="button primary" id="rn">Save</button>');$('#rn').onclick=()=>{let n=$('#vn').value.trim();if(!n)return;v.name=n;d.close();refreshEdit()};$('#deleteV').onclick=()=>{modal('Delete this variant?','<p class="notice">Remove '+esc(v.name)+' from this study?</p>',cancel+'<button class="button primary" id="confirmDel">Delete</button>');$('#confirmDel').onclick=()=>{project.variants=project.variants.filter(x=>x.id!==v.id);project.checked=project.checked.filter(id=>id!==v.id);project.active='base';$('#dialog').close();renderWorkspace();changed()}}}
function cost(v){return Number.isFinite(v.rate)&&Number.isFinite(v.quantity)?fmt(v.rate*v.quantity)+' '+(project.currency||'USD'):'Unpriced'}
function table(vs,rows){return '<div class="table-box"><table class="study-table"><thead><tr><th scope="col">Design property</th>'+vs.map(v=>'<th scope="col">'+esc(v.name)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(([l,cb])=>'<tr><th scope="row">'+l+'</th>'+vs.map(v=>'<td>'+esc(cb(v))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
const summary=v=>(params[v.system]||[]).map(([k,l,,,,u])=>l+' '+fmt(v[k])+u).join(' · ')||'—';
function compare(){let vs=project.variants.filter(v=>project.checked.includes(v.id));$('#compare').innerHTML='<div class="tab-head"><div><h2>Compare variants</h2><p>Review each system and its settings against the reference envelope.</p></div><button id="chooseVariants" class="button secondary">'+icon('sliders-horizontal')+'Select variants</button></div><div class="compare-cards">'+vs.map(v=>'<article class="compare-card"><canvas aria-label="'+esc(v.name)+' model"></canvas><div class="card-body"><h3>'+esc(v.name)+'</h3><small>'+code(v)+'</small></div><button class="button secondary small" data-edit="'+esc(v.id)+'">'+icon(v.id==='base'?'eye':'pencil')+(v.id==='base'?'View reference':'Edit variant')+'</button></article>').join('')+'</div>'+table(vs,[['Façade system',v=>systems[v.system].name],['Nature label',v=>systems[v.system].family],['Mechanism',v=>systems[v.system].mech],['Applied to',v=>v.id==='base'?'Whole building':hosts[systems[v.system].host]+(systems[v.system].host==='roof'?'':' · '+dirNames[v.elevation])],['Floor placement',v=>v.id==='base'?'All floors':floorName(v)],['Key parameters',summary],['Material',v=>v.id==='base'?existingFacades[v.existing||'granite'][0]:v.system==='ovf'?claddings[v.cladding||'terracotta']:v.system==='datepalm'?insulations[v.insul||'datepalm'][0]:v.system==='trellis'?(plants[v.plant]||plants.grape)[0]:v.system==='brick'?screens[v.screen||'brick'][0]:'—'],['Add-ons',v=>Object.keys(addons).filter(k=>v.addons?.[k]).map(k=>addons[k]).join(', ')||'—'],['Building form',v=>project.model?'Imported geometry':masses[v.mass||'stepped']],['Building rotation',v=>(v.rotation||0)+'°'],['Window-to-wall target',v=>project.model?'Imported geometry':(v.wwr??74)+'%'],['Installed cost estimate',cost]])+'<p class="footer-note">Costs use the installed quantity and unit rate entered in Design inspector.</p>';
 $$('#compare canvas').forEach((c,i)=>draw(c,buildScene(project,vs[i],{landscape:true}),cameraDefault(),{thumb:true}));$$('[data-edit]').forEach(n=>n.onclick=()=>{project.active=n.dataset.edit;setTab('workspace');changed()});
 $('#chooseVariants').onclick=()=>{let d=modal('Select comparison variants',project.variants.map(v=>'<label class="checkline"><input type="checkbox" value="'+esc(v.id)+'" '+(v.id==='base'?'checked disabled':project.checked.includes(v.id)?'checked':'')+'>'+esc(v.name)+'</label>').join(''),cancel+'<button class="button primary" id="applyChecked">Apply</button>');$('#applyChecked').onclick=()=>{project.checked=[...d.querySelectorAll('input:checked')].map(n=>n.value);d.close();compare();changed()}}}
// Leaf cover the trellis can carry: closer cables let the plants fill in more.
const trellisCover=v=>Math.min(v.coverage,Math.min(100,115-20*v.spacing));
// Illustrative numbers only: a toy formula so the finished layout can be previewed. Not simulation results.
function predictDemo(v){
 const base=project.variants.find(x=>x.id==='base')||v,g=(project.model?60:(base.wwr??74))/100,ori={all:1,W:.36,E:.30,S:.25,N:.09}[v.elevation]??1,dirTxt=dirNames[v.elevation]||'All elevations';
 const refCool=Math.round(150*(.75+.5*g)),refOver=900,uRef=(existingFacades[base.existing]||existingFacades.granite)[1];let red=0,why=[];
 if(v.system==='trellis'){const P=plants[v.plant]||plants.grape,cov=trellisCover(v)/100;red=.46*g*ori*.7*P[2]*(1-Math.exp(-2.5*cov))/(1-Math.exp(-1.75))*(1-.15*Math.abs(v.depth-.6));why=['Large glazed area (WWR '+Math.round(g*100)+'%) makes window shade the strongest lever',P[0]+' at '+fmt(cov*100)+'% cover blocks most summer sun on '+dirTxt.toLowerCase(),P[4]==='Deciduous'?'Leaves drop in winter, so winter sun still comes in':'Keeps its leaves in winter, so it also blocks winter sun']}
 else if(v.system==='brick'){const mat={brick:1,terracotta:1.02,grc:.95}[v.screen]??1;red=.27*g*ori*.8*Math.pow((1-v.coverage/100)/.8,1.4)*(1-.12*Math.exp(-v.depth/.25))*(.85+.25*(1-Math.exp(-v.screenThick/.06)))*mat;why=['Fixed shade cuts direct sun on '+dirTxt.toLowerCase()+' glass all year',fmt(v.coverage)+'% open area keeps some daylight and view','No water or maintenance needs']}
 else if(v.system==='ovf'){const cf={terracotta:1,stone:1.03,gfrc:.98,acp:.9,brick:1,biobased:1.02}[v.cladding]??1;red=(1-g)*ori*(.17+.25*(1-Math.exp(-v.cavity/.07)))*cf;why=['Ventilated cavity removes heat before it reaches the wall',fmt(v.cavity)+' m cavity gives steady airflow','Limited effect here because only '+Math.round((1-g)*100)+'% of the façade is opaque wall']}
 else if(v.system==='datepalm'){const m=insulations[v.insul]||insulations.datepalm,U0=uRef,U1=1/(1/U0+v.thick/m[1]);red=(1-g)*.2*(1-U1/U0);why=[fmt(v.thick)+' m of '+m[0].toLowerCase()+' takes the wall from U '+fmt(U0)+' to '+fmt(U1)+' W/m²K','Small effect because windows dominate heat gain in this building','Energy close to mineral insulation; the gain is mostly lower embodied carbon']}
 else if(v.system==='biopcm'){red=.85*Math.min(.15,(.02+.08*(1-Math.exp(-v.nightAch/3)))*(1-Math.min(1,Math.abs(v.melt-26)/6))*Math.pow(v.pcmThick/.02,.4));why=['Stores daytime heat and shifts the cooling peak',fmt(v.nightAch)+' ach night ventilation lets the PCM solidify again','Works only on nights cool enough to discharge it']}
 else if(v.system==='greenroof'){let top=.12+.06*(1-Math.exp(-v.substrate/.1))+.01*v.irrigation+.008*v.lai;red=top/Math.max(1,project.levels);why=['Top floor cooling drops about '+Math.round(top*100)+'%','Whole-building effect is small for a '+project.levels+'-storey building','Needs about '+fmt(v.irrigation)+' L/m²·day of irrigation']}
 else if(v.system==='custom'){red=.05;why=['Estimate based on generic shading geometry']}
 const pv=v.addons?.pv?Math.round(120+40*ori):0;if(pv)why.push('PV canopy adds about '+pv+' kWh/m² of canopy per year (reported separately)');
 return{cool:Math.round(refCool*(1-red)),diff:-(red*100),over:Math.round(refOver*(1-1.3*red)),why,refCool,refOver,red,g,ori}}

// Demo-only chart data. Invented shapes that follow the toy formula above; not simulation output.
const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],MW=[0,.005,.02,.05,.10,.155,.19,.185,.14,.08,.025,.005],MWS=MW.reduce((a,b)=>a+b,0);
const demoMonthly=(v,r)=>MW.map(w=>{let ref=r.refCool*w/MWS;if(v.id==='base')return +ref.toFixed(1);let f=v.system==='trellis'?.45+.95*w/.19:1;return +(ref*(1-r.red*f)).toFixed(1)});
const demoDay=(v,r)=>{const q=h=>(6+40*Math.exp(-((h-16)**2)/(2*3.4**2)))*(.6+.6*r.g),qmax=q(16);return Array.from({length:24},(_,h)=>{if(v.id==='base')return +q(h).toFixed(1);if(v.system==='biopcm'){let avg=Array.from({length:24},(_,k)=>q(k)).reduce((a,b)=>a+b)/24;return +((1-r.red)*(.62*q((h+22)%24)+.38*avg)).toFixed(1)}return +(q(h)*(1-r.red*1.4*q(h)/qmax)).toFixed(1)})};
const demoSda=(v,r)=>{let ref=Math.round(40+55*r.g);if(v.system==='trellis')return Math.round(ref-30*trellisCover(v)/100*(.6+.4*r.ori));if(v.system==='brick')return Math.round(ref-42*(1-v.coverage/100)*(.6+.4*r.ori));return ref};
const CARBON=v=>v.system==='ovf'?{brick:55,terracotta:62,stone:70,gfrc:60,acp:95,biobased:20}[v.cladding]??62:v.system==='datepalm'?(v.insul==='cork'?10:5):{trellis:18,brick:55,biopcm:34,greenroof:41,custom:40}[v.system]??40;
const COST={brick:4,trellis:3,ovf:2,datepalm:5,biopcm:2,greenroof:2,custom:3},COSTN={1:'High cost',2:'Medium-high cost',3:'Medium cost',4:'Low-medium cost',5:'Low cost'};
function demoCharts(ranked){
 if(!ranked.length)return;
 const base=project.variants.find(x=>x.id==='base'),rb=predictDemo(base),top3=ranked.slice(0,3),maxRed=Math.max(...ranked.map(x=>x.r.red),1e-6),maxOverCut=Math.max(...ranked.map(x=>rb.refOver-x.r.over),1);
 const S=x=>({name:x.v.name,short:x.v.name.split(' · ')[0],color:systems[x.v.system].color});
 lineChart($('#chMonthly'),{labels:MONTHS,unit:'kWh/m²',digits:1,labelAt:'peak',series:[{name:'Reference envelope',short:'Reference',color:'#6f7d74',dash:true,values:demoMonthly(base,rb)},...top3.map(x=>({...S(x),values:demoMonthly(x.v,x.r)}))]});
 let dayPick=[top3[0],ranked.find(x=>x.v.system==='biopcm')].filter((x,i,a)=>x&&a.indexOf(x)===i);
 lineChart($('#chDay'),{labels:Array.from({length:24},(_,h)=>String(h).padStart(2,'0')+':00'),unit:'W/m²',digits:1,series:[{name:'Reference envelope',short:'Reference',color:'#6f7d74',dash:true,values:demoDay(base,rb)},...dayPick.map(x=>({...S(x),values:demoDay(x.v,x.r)}))]});
 const best=ranked[0].v.id,sdaRef=demoSda(base,rb);
 scatter($('#chTrade'),{xLabel:'Less cooling than reference (%)',yLabel:'Daylight, sDA (% of floor)',accent:'#14b258',points:[{x:0,y:sdaRef,label:'Reference'},...ranked.map(x=>({x:-x.r.diff,y:demoSda(x.v,x.r),label:x.v.name.split(' · ')[0],highlight:x.v.id===best,extra:[{value:'#'+(ranked.indexOf(x)+1),label:'rank'}]}))]});
 const ow=ranked.find(x=>['window','wall'].includes(systems[x.v.system].host))||ranked[0],dirs=['N','E','S','W'];
 $('#chOrientTitle').textContent='Where '+ow.v.name.split(' · ')[0]+' works best';
 barChart($('#chOrient'),{labels:[...dirs.map(d=>dirNames[d]),'All sides'],values:[...dirs,'all'].map(d=>-predictDemo({...ow.v,elevation:d}).diff),color:systems[ow.v.system].color,unit:'% less cooling',note:'less cooling than reference'});
 scoreMatrix($('#chScores'),{cols:[{name:'Cooling'},{name:'Comfort'},{name:'Daylight'},{name:'Water'},{name:'Cost'}],rows:ranked.map(x=>{let sda=demoSda(x.v,x.r),water=x.v.system==='trellis'?3:x.v.system==='greenroof'?Math.max(1,5-x.v.irrigation):5;return{name:x.v.name,color:systems[x.v.system].color,scores:[1+4*x.r.red/maxRed,1+4*(rb.refOver-x.r.over)/maxOverCut,Math.max(1,Math.min(5,5-(sdaRef-sda)/7)),water,COST[x.v.system]??3],notes:[fmt((-x.r.diff).toFixed(1))+'% less cooling',fmt(rb.refOver-x.r.over)+' fewer overheating hours','sDA '+sda+'%',water===5?'No irrigation':'Needs irrigation',COSTN[COST[x.v.system]??3]]}})});
 // Peak load, month-by-hour saving, parameter sweeps and embodied carbon (all demo).
 const peak=x=>Math.max(...demoDay(x.v,x.r));
 hbar($('#chPeak'),{unit:'W/m²',digits:1,note:'peak cooling load on a hot July day',refLine:peak({v:base,r:rb}),items:[{label:'Reference',value:peak({v:base,r:rb}),color:'#6f7d74',ref:true},...[...ranked].sort((a,b)=>peak(a)-peak(b)).map(x=>({label:x.v.name.split(' · ')[0],value:peak(x),color:systems[x.v.system].color,extra:[{value:'−'+fmt((1-peak(x)/peak({v:base,r:rb}))*100,0)+'%',label:'vs reference peak'}]}))]});
 const top=ranked[0],refD=demoDay(base,rb),sysD=demoDay(top.v,top.r);
 $('#chHeatTitle').textContent='When '+top.v.name.split(' · ')[0]+' saves cooling';
 heatmap($('#chHeat'),{rows:MONTHS,cols:Array.from({length:24},(_,h)=>String(h).padStart(2,'0')),unit:'W/m² saved',values:MW.map(w=>refD.map((q,h)=>Math.max(0,(q-sysD[h])*w/.19)))});
 const sweep=(sys,key,vals,host,label)=>{let x=ranked.find(y=>y.v.system===sys);if(!x){$(host).closest('.chart-card').hidden=true;return}lineChart($(host),{labels:vals.map(n=>n+'%'),unit:'% less cooling',digits:1,series:[{...S(x),name:x.v.name+' · '+label,values:vals.map(n=>+(-predictDemo({...x.v,[key]:n}).diff).toFixed(1))}]})};
 sweep('trellis','coverage',[20,30,40,50,60,70,80,90,100],'#chSweepGreen','leaf coverage');
 sweep('brick','coverage',[10,20,30,40,50,60,70,80],'#chSweepScreen','open area');
 scatter($('#chCarbon'),{xLabel:'Less cooling than reference (%)',yLabel:'Embodied carbon (kgCO₂e/m²)',accent:'#14b258',corner:'Better ↘',yName:'embodied carbon',ySuffix:' kgCO₂e/m²',points:ranked.map(x=>({x:-x.r.diff,y:CARBON(x.v),label:x.v.name.split(' · ')[0],highlight:x.v.id===best}))});
}
function chartSection(){return '<h2 class="charts-head">Charts</h2><div class="chart-grid"><section class="chart-card wide"><h3>Monthly cooling demand</h3><p class="chart-sub">Reference envelope and the top three systems. Most of the saving falls in June to August.</p><div id="chMonthly"></div></section><section class="chart-card"><h3>Cooling load on a hot July day</h3><p class="chart-sub">Hourly load. PCM flattens the curve and moves the peak later.</p><div id="chDay"></div></section><section class="chart-card"><h3>Peak cooling load</h3><p class="chart-sub">Highest hourly load on a hot July day. The dashed line is the reference.</p><div id="chPeak"></div></section><section class="chart-card wide"><h3 id="chHeatTitle">When the saving happens</h3><p class="chart-sub">Cooling load saved by the top system, by month and hour. Darker means more saving.</p><div id="chHeat"></div></section><section class="chart-card"><h3 id="chOrientTitle">Where it works best</h3><p class="chart-sub">The same system on one elevation only; the bar on the right covers the whole building.</p><div id="chOrient"></div></section><section class="chart-card"><h3>What if: leaf coverage</h3><p class="chart-sub">Cooling saving as the climbing plants fill in.</p><div id="chSweepGreen"></div></section><section class="chart-card"><h3>What if: screen open area</h3><p class="chart-sub">More openings keep daylight but let in more sun.</p><div id="chSweepScreen"></div></section><section class="chart-card"><h3>Cooling saved vs embodied carbon</h3><p class="chart-sub">Carbon to make and install each system, per m² of system.</p><div id="chCarbon"></div></section><section class="chart-card wide"><h3>Cooling vs daylight</h3><p class="chart-sub">Window shades save more cooling but take away daylight. Hover a point for details.</p><div id="chTrade"></div></section><section class="chart-card wide"><h3>Scores across criteria</h3><p class="chart-sub">1 is weak, 5 is strong. Cost 5 means cheapest; water 5 means no irrigation.</p><div id="chScores"></div></section></div>'}
// Demo optimiser: tries every setting on a grid and keeps the best cooling saving after a small cost and carbon penalty,
// within two limits: daylight sDA at least 55% and irrigation at most 2.5 L/m²·day.
const SDA_MIN=55,WATER_MAX=2.5;
const OPTIONS={trellis:['plant',plants],brick:['screen',screens],ovf:['cladding',claddings],datepalm:['insul',insulations]};
const waterUse=v=>v.system==='trellis'?(plants[v.plant]||plants.grape)[3]*trellisCover(v)/100:v.system==='greenroof'?v.irrigation:0;
const penalty=v=>({trellis:1.5*v.depth+1/v.spacing,brick:12*v.screenThick+.5*v.depth,ovf:12*v.cavity+.02*CARBON(v),datepalm:10*v.thick+.03*CARBON(v),biopcm:.6*v.nightAch+110*v.pcmThick,greenroof:2*v.substrate+.1*v.irrigation+.05*v.lai}[v.system]??0);
function optimise(v){const ps=params[v.system]||[],opt=OPTIONS[v.system],base=project.variants.find(x=>x.id==='base'),sdaRef=demoSda(base,predictDemo(base));
 const fixed={brick:['spacing']}[v.system]||[],axes=ps.filter(p=>!fixed.includes(p[0])).map(([k,,min,max,step])=>{let n=Math.round((max-min)/step),pick=Math.max(1,Math.ceil(n/14)),vals=[];for(let i=0;i<=n;i+=pick)vals.push(+(min+i*step).toFixed(4));if(vals.at(-1)!==max)vals.push(max);return[k,vals]});
 if(opt)axes.push([opt[0],Object.keys(opt[1])]);let best=null,tried=0;
 const walk=(i,cand)=>{if(i===axes.length){tried++;const r=predictDemo(cand),sda=demoSda(cand,r),w=waterUse(cand);if(sda<SDA_MIN&&sda<sdaRef)return;if(w>WATER_MAX)return;if(v.system==='greenroof'&&cand.lai>1+1.2*cand.irrigation)return;const score=100*r.red-penalty(cand);if(!best||score>best.score)best={score,v:{...cand},r,sda,w};return}for(const x of axes[i][1])walk(i+1,{...cand,[axes[i][0]]:x})};
 walk(0,{...v});if(!best)return null;
 const b=best.v,limits=[];if(best.sda<SDA_MIN+2&&['trellis','brick'].includes(v.system))limits.push('Daylight (sDA ≥ '+SDA_MIN+'%)');if(best.w>WATER_MAX-.25)limits.push('Irrigation ≤ '+WATER_MAX+' L/m²·day');if(!limits.length)limits.push('Cost and carbon of going further');
 const settings=[...ps.filter(p=>!fixed.includes(p[0])).map(([k,l,,,,u])=>[l,fmt(k==='coverage'&&v.system==='trellis'?trellisCover(b):b[k],k==='pcmThick'?3:2)+u]),...(opt?[[{plant:'Plant',screen:'Screen material',cladding:'Cladding',insul:'Material'}[opt[0]],v.system==='trellis'?plants[b.plant][0]+' ('+plants[b.plant][1]+')':Array.isArray(opt[1][b[opt[0]]])?opt[1][b[opt[0]]][0]:opt[1][b[opt[0]]]]]:[])];
 return{...best,settings,limits,tried,nowSda:demoSda(v,predictDemo(v)),changed:[...ps.filter(p=>!fixed.includes(p[0])).map(p=>p[0]),...(opt?[opt[0]]:[])]}}
function optimiseSection(ranked){
 const rows=ranked.filter(x=>params[x.v.system]).map(x=>({x,o:optimise(x.v)})).filter(y=>y.o);if(!rows.length)return'';
 const top=rows.slice().sort((a,b)=>b.o.r.red-a.o.r.red)[0],total=rows.reduce((n,y)=>n+y.o.tried,0);
 return '<section class="opt-box"><div class="opt-head"><div><span class="top-label">Optimised settings</span><h3>Best after optimising: '+esc(systems[top.x.v.system].name)+'</h3><p><b>'+fmt((top.o.r.red*100).toFixed(1))+'% less cooling</b> with the settings below, against '+fmt((-top.x.r.diff).toFixed(1))+'% with the current settings.</p></div><button class="button primary small" data-apply="'+esc(top.x.v.id)+'">'+icon('check')+'Apply to variant</button></div>'+
 '<div class="opt-chips">'+top.o.settings.map(([l,val])=>'<span class="chip"><small>'+esc(l)+'</small>'+esc(val)+'</span>').join('')+'</div>'+
 '<div class="table-box"><table class="study-table opt-table"><thead><tr><th>System</th><th>Now</th><th>Optimised</th><th>Best settings</th><th>What limits it</th><th></th></tr></thead><tbody>'+
 rows.sort((a,b)=>b.o.r.red-a.o.r.red).map(({x,o})=>'<tr><th><i class="row-key" style="background:'+systems[x.v.system].color+'"></i>'+esc(x.v.name)+'</th><td>'+fmt((-x.r.diff).toFixed(1))+'%</td><td><b class="delta">'+fmt((o.r.red*100).toFixed(1))+'%</b></td><td class="why">'+o.settings.map(([l,val])=>esc(l)+' <b>'+esc(val)+'</b>').join(' · ')+'</td><td class="why">'+esc(o.limits.join(', '))+(o.r.red*100<-x.r.diff-.05?'<br><span class="warn">Current setting leaves only '+o.nowSda+'% daylight (sDA), below the '+SDA_MIN+'% limit</span>':'')+'</td><td><button class="button secondary small" data-apply="'+esc(x.v.id)+'">Apply</button></td></tr>').join('')+'</tbody></table></div>'+
 '<p class="footer-note">Frond tried '+total.toLocaleString()+' combinations. It keeps the largest cooling saving after a small cost and carbon penalty, with daylight sDA at least '+SDA_MIN+'% and irrigation at most '+WATER_MAX+' L/m²·day. Demo data; the trained model will run the same search.</p></section>'}
function bindApply(){$$('[data-apply]').forEach(n=>n.onclick=()=>{const v=project.variants.find(x=>x.id===n.dataset.apply);if(!v)return;const o=optimise(v);if(!o)return;for(const k of o.changed)v[k]=o.v[k];changed();results()})}
function results(){let vs=project.variants,demo=!!project.demo,pending='<td><span class="pending">Not predicted</span></td>';
 let rows=vs.map(v=>({v,r:predictDemo(v)})),ranked=rows.filter(x=>x.v.id!=='base').sort((a,b)=>a.r.diff-b.r.diff),order=new Map(ranked.map((x,i)=>[x.v.id,i+1])),best=ranked[0],max=Math.max(1,...ranked.map(x=>-x.r.diff));
 if(demo)rows=[...rows.filter(x=>x.v.id==='base'),...ranked];
 const top=demo&&best?'<div class="top-pick"><div class="top-rank">#1</div><div><span class="top-label">Best for this building</span><h3>'+esc(best.v.name)+'</h3><p><b>'+fmt(Math.abs(best.r.diff).toFixed(1))+'% less cooling</b> than the reference envelope · '+esc(systems[best.v.system].family)+'</p><ul>'+best.r.why.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></div></div>':'';
 const chart=demo?'<div class="rank-chart"><h3>Cooling demand reduction vs reference</h3>'+ranked.map(x=>'<div class="bar-row"><span class="bar-name">'+order.get(x.v.id)+'. '+esc(x.v.name)+'</span><span class="bar-track"><span class="bar-fill" style="width:'+(100*-x.r.diff/max)+'%;background:'+systems[x.v.system].color+'"></span></span><span class="bar-val">'+fmt((-x.r.diff).toFixed(1))+'%</span></div>').join('')+'</div>':'';
 const info=demo?'<div class="demo-banner">'+icon('chart-no-axes-column')+'<div><strong>Demo data</strong><p>These numbers are invented to preview the finished layout. They are not simulation or ML results.</p></div></div>':'<div class="result-info">'+icon('chart-no-axes-column')+'<div><strong>Predictions are pending</strong><p>The ML model is not trained yet. It will learn from about 2,000 EnergyPlus runs per system with the city weather file. When it is ready, each system gets a rank, its percentage difference from the reference and the main reasons.</p></div></div>';
 const cell=(x,k)=>{if(!demo)return pending;let r=x.r,base=x.v.id==='base';if(k==='rank')return '<td>'+(base?'Ref.':'<b>'+order.get(x.v.id)+'</b>')+'</td>';if(k==='cool')return '<td>'+(base?r.refCool:r.cool)+'</td>';if(k==='diff')return '<td>'+(base?'—':'<span class="delta">'+fmt(r.diff.toFixed(1))+'%</span>')+'</td>';if(k==='over')return '<td>'+(base?r.refOver:r.over)+'</td>';if(k==='why')return '<td class="why">'+(base?'Current envelope':esc(r.why[0]))+'</td>'};
 $('#results').innerHTML='<div class="tab-head"><div><h2>Ranking for this building</h2><p>Each system is ranked against the reference envelope for '+esc(project.location||'the selected city')+'.</p></div><div class="form-actions"><button class="button secondary" id="demoToggle">'+icon(demo?'eye':'sliders-horizontal')+(demo?'Hide demo data':'Show demo data')+'</button><button class="button secondary" id="resultCSV">'+icon('download')+'Export CSV</button></div></div>'+info+top+chart+(demo?optimiseSection(ranked)+chartSection():'')+'<h2 class="charts-head">'+(demo?'Full table':'')+'</h2><div class="table-box"><table class="study-table"><thead><tr><th>Rank</th><th>Variant</th><th>System</th><th>Cooling demand<br><small>kWh/m²·yr</small></th><th>Difference<br><small>vs reference</small></th><th>Occupied overheating<br><small>hours/yr</small></th><th>Main reason</th><th>Installed cost</th></tr></thead><tbody>'+rows.map(x=>'<tr>'+(demo?cell(x,'rank'):'<td>—</td>')+'<th>'+esc(x.v.name)+'</th><td>'+esc(systems[x.v.system].name)+'</td>'+(demo?cell(x,'cool')+cell(x,'diff')+cell(x,'over')+cell(x,'why'):pending.repeat(4))+'<td>'+esc(cost(x.v))+'</td></tr>').join('')+'</tbody></table></div><p class="footer-note">Add-ons (PV, light finish) appear beside the ranking. PV electricity is reported separately from cooling demand.</p>';
 if(demo){demoCharts(ranked);bindApply()}
 $('#demoToggle').onclick=()=>{project.demo=!demo;results();changed()};
 $('#resultCSV').onclick=()=>{let out=[['Rank','Variant','System','Nature label','Cooling demand (kWh/m²·yr)','Difference vs reference (%)','Occupied overheating (h/yr)','Main reasons','Status','Installed cost'],...rows.map(x=>{let b=x.v.id==='base',r=x.r;return demo?[b?'Reference':order.get(x.v.id),x.v.name,systems[x.v.system].name,systems[x.v.system].family,b?r.refCool:r.cool,b?'':r.diff.toFixed(1),b?r.refOver:r.over,b?'':r.why.join(' | '),'DEMO DATA, not simulated',cost(x.v)]:['',x.v.name,systems[x.v.system].name,systems[x.v.system].family,'','','','','Not predicted',cost(x.v)]})];download('frond-ranking'+(demo?'-DEMO':'')+'.csv',out.map(r=>r.map(s=>'"'+String(s).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}}
function exportGeometry(){
 const data=buildScene(project,active(),{landscape:false});let lines=['# Frond design geometry in metres, Z up','o '+active().id.replace(/[^a-zA-Z0-9_-]/g,'_')],i=1;for(let face of data.poly){for(let p of face.p)lines.push('v '+p.map(n=>n.toFixed(5)).join(' '));lines.push('f '+face.p.map((_,j)=>i+j).join(' '));i+=face.p.length}download('frond-'+active().name.replace(/[^a-z0-9_-]+/gi,'-')+'.obj',lines.join('\n'),'text/plain');toast('Variant geometry exported')
}
function exportStudy(){download((project.name.replace(/[^a-z0-9_-]+/gi,'-')||'frond')+'.frond.json',JSON.stringify(project),'application/json');toast('Study exported')}
function readStudy(j){
 if(j?.schema!=='frond-1'||!Array.isArray(j.variants)||!j.variants.some(v=>v.id==='base')||!j.variants.length||typeof j.name!=='string')throw Error('This is not a Frond study file.');
 function model(m){if(!m)return null;if(!Array.isArray(m.faces)||!m.faces.length||m.faces.length>30000||m.faces.some(f=>!Array.isArray(f.p)||f.p.length<3||f.p.some(p=>!Array.isArray(p)||p.length!==3||p.some(n=>!Number.isFinite(n)))))throw Error('The study contains invalid geometry.');return{...m,bounds:bounds(m.faces),rooms:Array.isArray(m.rooms)?m.rooms:[],stories:Array.isArray(m.stories)?m.stories:[]}}
 const number=(value,fallback,min,max)=>{const n=Number(value);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):fallback};
 const textValue=(value,fallback,limit=80)=>typeof value==='string'?value.slice(0,limit):fallback;
 const ranges={};for(const list of Object.values(params))for(const [k,,min,max] of list){ranges[k]=ranges[k]?[Math.min(ranges[k][0],min),Math.max(ranges[k][1],max)]:[min,max]}
 const p={...stateDefault(),...j};
 p.demo=!!j.demo;p.model=model(p.model);p.levels=Math.round(number(p.levels,1,1,120));p.name=textValue(p.name,'Imported study');p.location=textValue(p.location,'');p.use=textValue(p.use,'Building');p.currency=textValue(p.currency,'USD',8);
 const ids=new Set();
 p.variants=p.variants.map(v=>{
   if(!Object.hasOwn(systems,v.system)||typeof v.id!=='string'||!v.id||ids.has(v.id))throw Error('Invalid variant in study.');
   ids.add(v.id);
   const out={...structuredClone(paramDefaults),...v,name:textValue(v.name,'Design variant'),custom:model(v.custom),
     elevation:Object.hasOwn(dirNames,v.elevation)?v.elevation:'all',
     floor:v.floor==='all'?'all':String(Math.round(number(v.floor,1,1,p.levels))),
     room:textValue(v.room,'all',300),wwr:number(v.wwr,74,20,90),rotation:[0,90,180,270].includes(Number(v.rotation))?Number(v.rotation):0,
     mass:Object.hasOwn(masses,v.mass)?v.mass:'stepped',cladding:Object.hasOwn(claddings,v.cladding)?v.cladding:'terracotta',insul:Object.hasOwn(insulations,v.insul)?v.insul:'datepalm',plant:Object.hasOwn(plants,v.plant)?v.plant:'grape',screen:Object.hasOwn(screens,v.screen)?v.screen:'brick',existing:Object.hasOwn(existingFacades,v.existing)?v.existing:'granite',
     addons:{pv:!!v.addons?.pv,coating:!!v.addons?.coating},
     rate:Number.isFinite(v.rate)?Math.max(0,v.rate):null,quantity:Number.isFinite(v.quantity)?Math.max(0,v.quantity):null};
   for(const [k,[min,max]] of Object.entries(ranges))out[k]=number(v[k],paramDefaults[k],min,max);
   return out;
 });
 p.checked=Array.isArray(p.checked)?p.checked.filter(id=>ids.has(id)):p.variants.map(v=>v.id);
 if(!p.checked.includes('base'))p.checked.unshift('base');
 if(!ids.has(p.active))p.active='base';
 return p;
}
function importForm(mode='building'){
 let file=null;const modes={building:'Building',module:'Façade module',study:'Saved study'};let d=modal('Import a model','<div class="option-tabs">'+Object.entries(modes).map(([k,t])=>'<button data-mode="'+k+'" class="'+(k===mode?'active':'')+'">'+t+'</button>').join('')+'</div><p class="notice">'+(mode==='building'?'Start a new study from your building geometry. Export your current study first if you want to keep a separate copy.':mode==='module'?'Attach a custom module to a design variant. Model its width along X, outward projection along Y, and height along Z.':'Restore a previously exported project, its imported geometry and design variants.')+'</p><label class="drop" id="dropZone">'+icon('file-up')+'<span>Choose a file or drop it here</span><small>'+(mode==='building'?'OBJ, HBJSON or GeoJSON footprint':mode==='module'?'OBJ module':'Frond study JSON')+' · up to 20 MB</small><input type="file" id="fileInput" accept="'+(mode==='study'?'.json':mode==='module'?'.obj':'.obj,.hbjson,.json,.geojson')+'"></label><p id="fileMsg" class="field-hint"></p>'+
 (mode==='study'?'':'<div class="fields two" id="meshOptions">'+formSelect('units','OBJ units',{m:'Metres',mm:'Millimetres',cm:'Centimetres',ft:'Feet'},'m')+formSelect('up','OBJ up axis',{Z:'Z up',Y:'Y up'},'Z')+'</div>')+
 (mode==='building'?'<div class="fields two"><label class="field">Storeys (massing)<input id="storeys" type="number" value="1" min="1" max="120"></label><label class="field">Location<input id="newLoc" maxlength="70" placeholder="City, country"></label></div><p class="field-hint">HBJSON keeps rooms and windows. OBJ uses exposed faces. GeoJSON footprints generate conceptual storeys and windows.</p>':'')+'<p id="importErr" role="alert" class="error"></p>',cancel+'<button class="button primary" id="confirmImport" disabled>'+icon('upload')+(mode==='study'?'Open study':mode==='module'?'Attach module':'Import building')+'</button>');
 d.querySelectorAll('[data-mode]').forEach(n=>n.onclick=()=>importForm(n.dataset.mode));
 function choose(f){if(!f)return;file=f;$('#fileMsg').textContent=f.name;$('#importErr').textContent='';$('#confirmImport').disabled=false}
 if(mode!=='study'){const sample=mode==='module'?'Folded-screen.obj':'Studio-office.hbjson',row=document.createElement('div');row.className='sample-choices';row.innerHTML='<button id="tryExample" type="button">'+icon('box')+'Try sample file</button><a download href="examples/'+sample+'">Download sample</a>';$('#dropZone').after(row);row.querySelector('button').onclick=async()=>{try{const res=await fetch('examples/'+sample);if(!res.ok)throw Error();choose(new File([await res.blob()],sample));}catch{$('#importErr').textContent='The sample could not be loaded.'}}}
 $('#fileInput').onchange=e=>choose(e.target.files[0]);let z=$('#dropZone');z.ondragover=e=>{e.preventDefault();z.classList.add('over')};z.ondragleave=()=>z.classList.remove('over');z.ondrop=e=>{e.preventDefault();z.classList.remove('over');choose(e.dataTransfer.files[0])};
 $('#confirmImport').onclick=async()=>{let btn=$('#confirmImport');btn.disabled=true;try{if(!file||file.size>20*1024*1024)throw Error('Choose a file smaller than 20 MB.');let txt=await file.text();if(mode==='study'){project=readStudy(JSON.parse(txt))}
 else{let m=parseModel(txt,file.name,{units:$('#units').value,up:$('#up').value,storeys:Number($('#storeys')?.value)||1});if(mode==='module'){if(m.faces.length>650)throw Error('Simplify this repeated module to 650 faces or fewer.');let a=active();if(a.id==='base'){a={...structuredClone(a),id:uid(),name:'Custom façade'};project.variants.push(a);project.checked.push(a.id);project.active=a.id}a.custom=m;a.system='custom';a.name=file.name.replace(/\.[^.]+$/,'').slice(0,50)}
 else{let next=stateDefault();next.name=file.name.replace(/\.[^.]+$/,'').slice(0,70);next.model=m;next.location=$('#newLoc').value.trim();next.use='Building';next.levels=m.stories.length||Math.max(1,Math.min(120,Math.round(Number($('#storeys').value)||1)));next.variants=next.variants.slice(0,2);next.checked=next.variants.map(v=>v.id);next.active='base';project=next}}
 camera=workCam();viewOptions.cut=0;view='Axonometric';$('#cameraName').textContent=view;d.close();setTab('workspace');changed();toast(mode==='module'?'Façade module attached':mode==='study'?'Study restored':'Building imported')}catch(ex){$('#importErr').textContent=ex.message||'Could not read this file.';btn.disabled=false}}
}
function viewportEvents(){
 const cv=$('#scene');let pointers=new Map(),lastDist=0,drag=null;
 cv.onpointerdown=e=>{cv.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false,pan:e.shiftKey||e.button===1||tool==='hand'};if(pointers.size===2){let [p,q]=[...pointers.values()];lastDist=Math.hypot(p[0]-q[0],p[1]-q[1])}};
 cv.onpointermove=e=>{if(!pointers.has(e.pointerId)||!drag)return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){let[p,q]=[...pointers.values()],dist=Math.hypot(p[0]-q[0],p[1]-q[1]);if(lastDist>0)camera.zoom=Math.max(.28,Math.min(4,camera.zoom*dist/lastDist));lastDist=dist;drag.moved=true;requestDraw();return}let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>3)drag.moved=true;if(drag.pan){camera.px+=dx;camera.py+=dy}else if(tool!=='select'){camera.az-=dx*.009;camera.el=Math.max(.07,Math.min(1.55,camera.el+dy*.009));view='Custom view';$('#cameraName').textContent=view}drag.x=e.clientX;drag.y=e.clientY;requestDraw()};
 cv.onpointerup=e=>{if(tool==='select'&&drag&&!drag.moved){let rect=cv.getBoundingClientRect(),o=pick(hit,e.clientX-rect.left,e.clientY-rect.top);if(o?.dir){if(active().id==='base')toast((dirNames[o.dir]||'')+' elevation · '+(o.room||'Original envelope'));else{active().elevation=o.dir;refreshEdit();toast((dirNames[o.dir]||'')+' elevation selected'+(o.room?' · '+o.room:''))}}}pointers.delete(e.pointerId);if(!pointers.size)drag=null;else if(drag){let [p]=pointers.values();drag.x=p[0];drag.y=p[1];drag.moved=true}};cv.onpointercancel=e=>{pointers.delete(e.pointerId);drag=null};
 cv.onwheel=e=>{e.preventDefault();camera.zoom=Math.min(4,Math.max(.28,camera.zoom*Math.exp(-e.deltaY*.0015)));requestDraw()};cv.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','Home'].includes(e.key)){e.preventDefault();if(e.key==='Home')camera=workCam();else if(e.key==='+'||e.key==='-')camera.zoom=Math.max(.28,Math.min(4,camera.zoom*(e.key==='+'?1.15:.87)));else{camera.az+=(e.key==='ArrowLeft'?.14:e.key==='ArrowRight'?-.14:0);camera.el=Math.max(.07,Math.min(1.55,camera.el+(e.key==='ArrowUp'?.09:e.key==='ArrowDown'?-.09:0)))}requestDraw()}};
}
