 trigger('#projectMenu',e=>menu(e.currentTarget,[['Project details',projectForm],['Open saved study',()=>importForm('study')],['Export study',exportStudy],['Export variant geometry (OBJ)',exportGeometry],['Open demo project',()=>{modal('Open Terrace Office?','<p class="notice">This replaces the current workspace. Export your study first to keep it.</p>',cancel+'<button id="openDemo" class="button primary">Open demo</button>');$('#openDemo').onclick=()=>{project=stateDefault();camera=workCam();viewOptions.cut=0;view='Axonometric';$('#cameraName').textContent=view;$('#dialog').close();setTab('workspace');changed()}}]]));
 trigger('#cameraBtn',e=>menu(e.currentTarget,Object.entries({'Axonometric':[-2.38,.45],'South elevation':[-Math.PI/2,.03],'West elevation':[Math.PI,.03],'East elevation':[0,.03],'North elevation':[Math.PI/2,.03],'Top view':[-Math.PI/2,Math.PI/2-.001]}).map(([name,angles])=>[name,()=>{camera={...cameraDefault(),az:angles[0],el:angles[1]};view=name;$('#cameraName').textContent=name;requestDraw()},view===name])));
 trigger('#layersBtn',e=>{let p=popAt(e.currentTarget,'<div class="poph">View layers</div>'+Object.entries({grid:'Ground grid',context:'Demo site context',landscape:'Demo landscape',shadows:'Cast shadows',wire:'Technical view'}).filter(([k])=>!project.model||!['context','landscape'].includes(k)).map(([k,t])=>'<label><input type="checkbox" data-layer="'+k+'" '+(viewOptions[k]?'checked':'')+'>'+t+'</label>').join('')+'<label>Section <select id="cutView" class="std"><option value="0">Exterior</option>'+Array.from({length:project.levels},(_,i)=>'<option value="'+(i+1)+'" '+(viewOptions.cut===i+1?'selected':'')+'>Level '+(i+1)+'</option>').join('')+'</select></label>');p.querySelectorAll('[data-layer]').forEach(n=>n.onchange=()=>{viewOptions[n.dataset.layer]=n.checked;requestDraw(true)});$('#cutView').onchange=e=>{viewOptions.cut=Number(e.target.value);$('#viewLabel').textContent=viewOptions.cut?'Section · Level '+viewOptions.cut:'Exterior view';requestDraw(true)}});
 trigger('#expandBtn',()=>{$('.model-pane').classList.toggle('expanded');requestDraw()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#pop').innerHTML='';$('.model-pane').classList.remove('expanded');requestDraw()}});document.addEventListener('pointerdown',e=>{if(!e.target.closest('.popover,#cameraBtn,#layersBtn,#projectMenu'))$('#pop').innerHTML=''});$('#dialog').onclick=e=>{if(e.target===$('#dialog')){let r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}};
 sunPanel();requestAnimationFrame(animate);viewportEvents();new ResizeObserver(()=>{requestDraw();drawThumbs()}).observe($('#viewArea'));window.addEventListener('resize',()=>{if(tab==='compare')compare();if(tab==='results'&&project.demo)results();$('#pop').innerHTML=''});window.addEventListener('hashchange',()=>setTab(location.hash.slice(1)));document.addEventListener('visibilitychange',()=>{if(document.hidden&&saveTimer){clearTimeout(saveTimer);persist()}})
